() => { 
  // Try to remove all overlays
  const overlays = document.querySelectorAll('div[id*="wm-"], div[class*="overlay"], div[class*="modal"], div[id*="overlay"], div[id*="modal"]');
  let removed = 0;
  overlays.forEach(o => { o.remove(); removed++; });
  return { overlaysRemoved: removed, bodyChildren: document.body.children.length };
}

() => {
  // Get text content of body to see what's there
  const body = document.body;
  const allText = body.innerText || body.textContent;
  return allText.substring(0, 8000);
}

() => {
  // Try to get HTML content
  const body = document.body;
  if (!body) return { error: 'No body found' };
  return { 
    bodyTextLength: (body.innerText || '').length, 
    bodyHTMLLength: body.innerHTML.length,
    title: document.title,
    url: window.location.href,
    sample: (body.innerText || '').substring(0, 1000)
  };
}
